DOMAIN_FILES=('final_attempts.py','native_replicate_attempts.py','native_unmanaged_cli.py', 'run_native_scientific6.py', 'run_native_final_child.py', 'native_final_dispatch.py', 'native_scientific_launch.py', 'native_whole_team.py', 'native_shell_context.py', 'native_cli_callback_custody.py', 'native_git_repository_backup.py', 'native_bridge_backup.py', 'native_control_custody.py', 'native_relay_backup.py', 'native_cli_tool_receipt.py', 'native_cli_tool_overlay.py', 'native_mcp_tool_terminal.py', 'native_scientific_http.py', 'native_scientific_owner.py', 'native_mysql_backup.py', 'native_mysql_runtime.py', 'native_cgroup_launch.py', 'admission_gate.py', 'native_budget_park.py', 'bootstrap.py', 'bridge.py', 'native_git_http.py', 'git_http_uds_front.py', 'budget.py', 'collector.py', 'common.py', 'feasibility_relay.py', 'final_authority.py', 'final_binding.py', 'final_host_rpc.py', 'final_queue.py', 'git_remote_agensh.py', 'manifest.py', 'model_capacity.py', 'mcp_uds_client.py', 'native_mcp_bridge.py', 'native_gitea.py', 'native_gitea_scope.py', 'native_gitea_backend.py', 'native_stage_binding.py', 'native_mcp_inputs.py', 'native_mcp_config.py', 'native_team_owner.py', 'native_sandbox.py', 'native_sdk_uid_launcher.py', 'native_sdk_public_runtime.py', 'native_delivery.py', 'native_worker_launch.py', 'native_mcp_overlay.py', 'native_mcp_policy.py', 'native_mattermost_scope.py', 'native_mattermost_backend.py', 'native_candidate_policy.py', 'native_evaluation_consistency.py', 'native_evaluator_custody.py', 'native_final_profile.py', 'native_final_runtime.py', 'native_images.py', 'native_inert_archive.py', 'native_k3.py', 'native_k3_original.py', 'native_materialization.py', 'native_model_port.py', 'native_space.py', 'native_space_original.py', 'native_terminal_original.py', 'protocol.py', 'scientific_profile.py', 'scientific_relay.py', 'snapshot.py', 'native_service_cut.py', 'native_sqlite_backup.py', 'native_writer_fence.py', 'native_scientific_bootstrap.py', 'native_model_tool_parent.py', 'v21_inputs.py')
DOMAIN_ASSETS=('native-budget-park-v1/native_startup_hold.ts', 'native-git-context-v1/native_git_bash_env.sh', 'native-cli-tool-receipt-v1/native_cli_tool_receipt.mjs', 'NATIVE_MYSQL_PUBLIC_RUNTIME_CONSUMED.json', 'native-cgroup-preexec-v1/cgroup_preexec.c', 'native-cgroup-preexec-v1/cgroup-preexec', 'native-budget-park-v1/budget_pause_clock.ts', 'native-budget-park-v1/acp_socket_channel.ts', 'native-budget-park-v1/main.ts', 'bootstrap-scientific.sh', 'bootstrap-mm-conditional-v2/bootstrap.sh.conditional', 'NATIVE_CANDIDATE_POLICY_ORIGIN.json', 'NATIVE_FINAL_CODE_ORIGIN.json', 'NATIVE_K3_ORIGIN.json', 'NATIVE_SPACE_ORIGIN.json', 'NATIVE_TERMINAL_ORIGIN.json', 'NATIVE_PUBLIC105_CONSUMED.json', 'NATIVE_MCP_DECLARATIONS_CONSUMED.json', 'native-mcp-public-metadata/gitea-wire.json', 'native-mcp-public-metadata/mattermost-wire.json')
def compile_profile(code,*,source_bundle_sha256,model_policy_sha256,evaluator_root,image_mapping_sha256,dependency_freeze_sha256):
    code=Path(code);base=Path(__file__).resolve().parent;origin=strict((base/'NATIVE_FINAL_CODE_ORIGIN.json').read_bytes())
    for v in (source_bundle_sha256,model_policy_sha256,image_mapping_sha256,dependency_freeze_sha256):sha(v)
    need(code.is_absolute()and code.resolve()==code,'NATIVE_CODE_CANONICAL_ROOT')
    actual={p.name:hash_file(p)['sha256']for p in code.glob('*.py')};expected={n:h for n,h in origin['files'].items()if n.endswith('.py')};need(actual==expected,'NATIVE_PUBLIC_CODE_EXACT_ORIGINAL')
    for name in ('config.json','original-images-metadata.json'):need(hash_file(code/name)['sha256']==origin['files'][name],'NATIVE_PUBLIC_CONFIG_OR_INVENTORY_CHANGED')
    return {'schema':'count14-agensh-native-v21-profile-v1','protocol':'v2.1','native_code_sha256':origin['files'],'domain_code_sha256':{n:hash_file(base/n)['sha256']for n in DOMAIN_FILES},'domain_asset_sha256':{n:hash_file(base/n)['sha256']for n in DOMAIN_ASSETS},'source_bundle_sha256':source_bundle_sha256,'source_index':hash_file(code/'source-manifest.json'),'model_policy_sha256':model_policy_sha256,'evaluator_assets':{n:hash_file(Path(evaluator_root)/n)for n in ASSETS},'image_mapping_sha256':image_mapping_sha256,'dependency_freeze_sha256':dependency_freeze_sha256,'finalization_turns':96,'context_window':262144,'hidden_feedback_to_search':False}
def verify_profile(profile,expected_sha256,code,*,source_bundle_sha256,model_policy_sha256,evaluator_root,image_mapping_sha256,dependency_freeze_sha256):
    need(digest(profile)==sha(expected_sha256),'NATIVE_PROFILE_PIN')
    expected=compile_profile(code,source_bundle_sha256=source_bundle_sha256,model_policy_sha256=model_policy_sha256,evaluator_root=evaluator_root,image_mapping_sha256=image_mapping_sha256,dependency_freeze_sha256=dependency_freeze_sha256)
    need(profile==expected,'NATIVE_PROFILE_INPUT_OR_RUNTIME_CHANGED');return profile
